import { defineUserSignupFields } from "wasp/server/auth";

export const userSignupFields = defineUserSignupFields({
  username: async (data: any) => {
    const username = data.username;
    if (typeof username !== "string" || !username) {
      throw new Error("Username is required");
    }
    return username;
  },
  role: async (data: any) => {
    const role = data.role;
    if (typeof role !== "string" || !role) {
      throw new Error("Role is required");
    }
    if (role !== "CUSTOMER" && role !== "AGENT" && role !== "MANAGER") {
      throw new Error("Invalid role");
    }
    return role;
  },
});

import type { OnAfterSignupHook } from "wasp/server/auth";

export const onAfterSignup: OnAfterSignupHook = async ({
  providerId,
  user,
  prisma,
  req,
}) => {
  const password = req.body?.password;
  if (password) {
    await prisma.user.update({
      where: { id: user.id },
      data: { password: password },
    });
  }
};

import { createProviderId, sanitizeAndSerializeProviderData, createUser } from "wasp/server/auth";

export const seedData = async (prisma: any) => {
  const userCount = await prisma.user.count();
  if (userCount > 0) {
    console.log("Database already has users, skipping seed.");
    return;
  }

  const usersToSeed = [
    { username: "manager", password: "password123", role: "MANAGER" },
    { username: "agent1", password: "password123", role: "AGENT" },
    { username: "agent2", password: "password123", role: "AGENT" },
    { username: "customer1", password: "password123", role: "CUSTOMER" },
  ];

  for (const u of usersToSeed) {
    const providerId = createProviderId("username", u.username);
    const providerData = await sanitizeAndSerializeProviderData<"username">({
      hashedPassword: u.password,
    });
    await createUser(providerId, providerData, {
      username: u.username,
      password: u.password,
      role: u.role,
    });
  }
  console.log("Database seeding completed successfully.");
};

import { HttpError } from "wasp/server";

export const getTickets = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  return context.entities.Ticket.findMany({
    include: {
      assignee: true,
      creator: true,
    },
    orderBy: {
      createdAt: "desc",
    },
  });
};

export const getAgents = async (args: any, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }
  const agents = await context.entities.User.findMany({
    where: { role: "AGENT" },
    include: {
      ticketsAssigned: {
        where: { status: { not: "RESOLVED" } },
      },
    },
  });
  return agents.map((agent: any) => ({
    id: agent.id,
    username: agent.username,
    role: agent.role,
    workload: agent.ticketsAssigned.length,
  }));
};

import { HttpError } from "wasp/server";

export const createTicket = async (
  args: { title: string; description: string; priority: "HIGH" | "MEDIUM" | "LOW" },
  context: any
) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  let durationMs = 0;
  if (args.priority === "HIGH") {
    durationMs = 3600 * 1000;
  } else if (args.priority === "MEDIUM") {
    durationMs = 14400 * 1000;
  } else if (args.priority === "LOW") {
    durationMs = 86400 * 1000;
  } else {
    throw new HttpError(400, "Invalid priority");
  }
  const slaDeadline = new Date(Date.now() + durationMs);

  const agents = await context.entities.User.findMany({
    where: { role: "AGENT" },
    include: {
      ticketsAssigned: {
        where: { status: { not: "RESOLVED" } },
      },
    },
  });

  let assignedAgentId: number | null = null;
  if (agents.length > 0) {
    const agentWorkloads = agents.map((agent: any) => ({
      agent,
      workload: agent.ticketsAssigned.length,
    }));

    agentWorkloads.sort((a: any, b: any) => {
      if (a.workload !== b.workload) {
        return a.workload - b.workload;
      }
      return a.agent.id - b.agent.id;
    });

    assignedAgentId = agentWorkloads[0].agent.id;
  }

  return context.entities.Ticket.create({
    data: {
      title: args.title,
      description: args.description,
      priority: args.priority,
      slaDeadline,
      creatorId: context.user.id,
      assigneeId: assignedAgentId,
    },
    include: {
      assignee: true,
      creator: true,
    },
  });
};

export const simulateSlaBreach = async (args: { ticketId: number }, context: any) => {
  if (!context.user) {
    throw new HttpError(401, "Unauthorized");
  }

  const ticket = await context.entities.Ticket.findUnique({
    where: { id: args.ticketId },
    include: { assignee: true, creator: true },
  });

  if (!ticket) {
    throw new HttpError(404, "Ticket not found");
  }

  const newCreatedAt = new Date(ticket.createdAt.getTime() - 2 * 3600 * 1000);
  const newSlaDeadline = new Date(ticket.slaDeadline.getTime() - 2 * 3600 * 1000);

  let updatedTicket = await context.entities.Ticket.update({
    where: { id: args.ticketId },
    data: {
      createdAt: newCreatedAt,
      slaDeadline: newSlaDeadline,
    },
    include: { assignee: true, creator: true },
  });

  const isBreached =
    newSlaDeadline.getTime() < Date.now() &&
    updatedTicket.status !== "RESOLVED" &&
    !updatedTicket.isEscalated;

  if (isBreached) {
    const managers = await context.entities.User.findMany({
      where: { role: "MANAGER" },
      orderBy: { id: "asc" },
    });

    const managerToAssign = managers[0] || null;

    updatedTicket = await context.entities.Ticket.update({
      where: { id: args.ticketId },
      data: {
        isEscalated: true,
        assigneeId: managerToAssign ? managerToAssign.id : updatedTicket.assigneeId,
      },
      include: { assignee: true, creator: true },
    });
  }

  return updatedTicket;
};

import React from "react";
import { LoginForm, SignupForm, FormItemGroup, FormLabel, FormError } from "wasp/client/auth";
import { Link } from "react-router";

export function LoginPage() {
  return (
    <Layout>
      <LoginForm />
